#[tokio::test]
#[ignore]
async fn test_deploy_upgrade() {
    // use super::CollateralUpgradeableV2;

    // parameters for miner to deposit collateral
    let miner_alpha_hotkey = [3u8; 32];

    // set timeout as 1000 second, make sure the trustee can deny the reclaim in time
    let decision_timeout = 1000u64;

    let proxied = set_test_env(&miner_alpha_hotkey, decision_timeout)
        .await
        .unwrap();

    let contract_hotkey = proxied.CONTRACT_HOTKEY().call().await.unwrap();
    let contract_coldkey = proxied.CONTRACT_COLDKEY().call().await.unwrap();

    // Get the provider from the existing contract
    let provider = proxied.provider();

    // Check version before upgrade
    let version_before = proxied.getVersion().call().await.unwrap();
    println!("Version before upgrade: {}", version_before);
    assert_eq!(version_before, 1);

    // Deploy new implementation V2
    let new_implementation = CollateralUpgradeableV2::deploy(provider).await.unwrap();
    println!(
        "New implementation deployed at: {:?}",
        new_implementation.address()
    );

    // Perform upgrade using upgradeToAndCall with empty data
    let tx = proxied.upgradeToAndCall(*new_implementation.address(), Bytes::new());
    let pending_tx = tx.send().await.unwrap();
    let receipt = pending_tx.get_receipt().await.unwrap();

    // Check for ContractUpgraded event
    for log in receipt.inner.logs() {
        if let Ok(event) = CollateralUpgradeable::ContractUpgraded::decode_log(&log.inner) {
            println!(
                "======================== ContractUpgraded event ================================"
            );
            println!("newVersion: {:?}", event.newVersion);
            println!("newImplementation: {:?}", event.newImplementation);
            println!("=========================================================================");
            assert_eq!(event.newVersion, U256::from(2));
            assert_eq!(event.newImplementation, *new_implementation.address());
        }
    }

    // Verify the upgrade was successful by checking the version
    let version_after = proxied.getVersion().call().await.unwrap();
    println!("Version after upgrade: {}", version_after);
    assert_eq!(version_after, 2);

    // Verify state is preserved after upgrade
    let contract_hotkey_v2 = proxied.CONTRACT_HOTKEY().call().await.unwrap();
    let contract_coldkey_v2 = proxied.CONTRACT_COLDKEY().call().await.unwrap();
    assert_eq!(contract_hotkey_v2, contract_hotkey);
    assert_eq!(contract_coldkey_v2, contract_coldkey);
}

async fn trustee_deny(
    proxied: &CollateralUpgradeableInstance<impl Provider>,
    reclaim_id: U256,
) -> Result<(), anyhow::Error> {
    let tx = proxied.denyReclaimRequest(
        reclaim_id,
        "https://www.tplr.ai/".to_string(),
        FixedBytes::from_slice(&[
            26u8, 9u8, 245u8, 1u8, 14u8, 0u8, 17u8, 59u8, 89u8, 65u8, 234u8, 75u8, 0u8, 12u8, 12u8,
            13u8,
        ]),
    );
    let pending_tx = tx.send().await.unwrap();
    let receipt = pending_tx.get_receipt().await.unwrap();
    for log in receipt.inner.logs() {
        if let Ok(event) = CollateralUpgradeable::Denied::decode_log(&log.inner) {
            println!("======================== Denied event ================================");
            println!("reclaimRequestId: {:?}", event.reclaimRequestId);
            println!("url: {:?}", event.url);
            println!("urlContentMd5Checksum: {:?}", event.urlContentMd5Checksum);
            println!("=========================================================================");
        }
    }

    let reclaim = proxied.reclaims(reclaim_id).call().await.unwrap();
    assert_eq!(reclaim.amount, 0);
    assert_eq!(reclaim.alphaAmount, 0);

    Ok(())
}

async fn trustee_slash(
    proxied: &CollateralUpgradeableInstance<impl Provider>,
    hotkey: &[u8; 32],
    node_id: &[u8; 16],
) -> Result<(), anyhow::Error> {
    let amount = proxied
        .collaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    let alpha_amount = proxied
        .alphaCollaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();

    // slash half of the collaterals
    let tx = proxied.slashCollateral(
        FixedBytes::from_slice(hotkey),
        FixedBytes::from_slice(node_id),
        amount,
        alpha_amount,
        "https://www.tplr.ai/".to_string(),
        FixedBytes::from_slice(&[
            26u8, 9u8, 245u8, 1u8, 14u8, 0u8, 17u8, 59u8, 89u8, 65u8, 234u8, 75u8, 0u8, 12u8, 12u8,
            13u8,
        ]),
    );
    let pending_tx = tx.send().await.unwrap();
    let receipt = pending_tx.get_receipt().await.unwrap();
    for log in receipt.inner.logs() {
        if let Ok(event) = CollateralUpgradeable::Slashed::decode_log(&log.inner) {
            println!("======================== Slashed event ================================");
            println!("hotkey: {:?}", event.hotkey);
            println!("nodeId: {:?}", event.nodeId);
            println!("miner: {:?}", event.miner);
            println!("amount: {:?}", event.slashAmount);
            println!("alphaAmount: {:?}", event.slashAlphaAmount);
            println!("url: {:?}", event.url);
            println!("urlContentMd5Checksum: {:?}", event.urlContentMd5Checksum);
            println!("=========================================================================");
        }
    }

    let amount = proxied
        .collaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    let alpha_amount = proxied
        .alphaCollaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    let miner = proxied
        .nodeToMiner(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    assert_eq!(amount, 0);
    assert_eq!(alpha_amount, 0);
    assert_eq!(miner, Address::ZERO);

    Ok(())
}

async fn miner_reclaim(
    proxied: &CollateralUpgradeableInstance<impl Provider>,
    hotkey: &[u8; 32],
    node_id: &[u8; 16],
    signer_public_key: &[u8; 32],
) -> Result<U256, anyhow::Error> {
    let tx = proxied.reclaimCollateral(
        FixedBytes::from_slice(hotkey),
        FixedBytes::from_slice(node_id),
        FixedBytes::from_slice(signer_public_key),
        "https://www.tplr.ai/".to_string(),
        FixedBytes::from_slice(&[
            26u8, 9u8, 245u8, 1u8, 14u8, 0u8, 17u8, 59u8, 89u8, 65u8, 234u8, 75u8, 0u8, 12u8, 12u8,
            13u8,
        ]),
    );
    let pending_tx = tx.send().await.unwrap();
    let receipt = pending_tx.get_receipt().await.unwrap();

    let mut reclaim_id = U256::from(0);

    for log in receipt.inner.logs() {
        if let Ok(event) = CollateralUpgradeable::ReclaimProcessStarted::decode_log(&log.inner) {
            reclaim_id = event.reclaimRequestId;
            println!(
                "======================== ReclaimProcessStarted event ================================"
            );
            println!("reclaim_id: {:?}", reclaim_id);
            println!("hotkey: {:?}", event.hotkey);
            println!("nodeId: {:?}", event.nodeId);
            println!("miner: {:?}", event.miner);
            println!("amount: {:?}", event.amount);
            println!("alphaColdkey: {:?}", event.alphaColdkey);
            println!("alphaAmount: {:?}", event.alphaAmount);
            println!(
                "==============================================================================="
            );
        }
    }

    println!("reclaim_id: {:?}", reclaim_id);

    let reclaim = proxied.reclaims(reclaim_id).call().await.unwrap();
    println!("reclaim: {:?}", reclaim.denyTimeout);
    assert_eq!(
        reclaim.alphaColdkey,
        FixedBytes::from_slice(signer_public_key)
    );

    Ok(reclaim_id)
}
async fn miner_deposit(
    proxied: &CollateralUpgradeableInstance<impl Provider>,
    hotkey: &[u8; 32],
    node_id: &[u8; 16],
    miner_alpha_hotkey: &[u8; 32],
    amount: U256,
    alpha_amount: U256,
) -> Result<(), anyhow::Error> {
    let tx = proxied
        .deposit(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
            FixedBytes::from_slice(miner_alpha_hotkey),
            alpha_amount,
        )
        .value(amount);
    let pending_tx = tx.send().await.unwrap();
    let receipt = pending_tx.get_receipt().await.unwrap();
    for log in receipt.inner.logs() {
        if let Ok(event) = CollateralUpgradeable::Deposit::decode_log(&log.inner) {
            println!("======================== Deposit event ================================");
            println!("hotkey: {:?}", event.hotkey);
            println!("nodeId: {:?}", event.nodeId);
            println!("miner: {:?}", event.miner);
            println!("amount: {:?}", event.amount);
            println!("alphaHotkey: {:?}", event.alphaHotkey);
            println!("alphaAmount: {:?}", event.alphaAmount);
            println!("=========================================================================");
        }
    }

    let miner = proxied
        .nodeToMiner(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    assert_eq!(miner, get_signer().address());

    let collaterals = proxied
        .collaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();
    assert_eq!(collaterals, amount);

    let alpha_collaterals = proxied
        .alphaCollaterals(
            FixedBytes::from_slice(hotkey),
            FixedBytes::from_slice(node_id),
        )
        .call()
        .await
        .unwrap();

    if alpha_collaterals > alpha_amount {
        assert!((alpha_collaterals - alpha_amount) < U256::from(100));
    } else {
        assert!((alpha_amount - alpha_collaterals) < U256::from(100));
    }

    Ok(())
}

async fn set_test_env(
    miner_alpha_hotkey: &[u8; 32],
    decision_timeout: u64,
) -> Result<CollateralUpgradeableInstance<impl Provider>, anyhow::Error> {
    // as contract hotkey
    let alpha_hotkey = [2u8; 32];

    let client = OnlineClient::<PolkadotConfig>::from_url(LOCAL_WS_URL)
        .await
        .unwrap();

    // set up local subtensor network
    disable_whitelist(&client).await.unwrap();
    let netuid = create_subnet(&client, &miner_alpha_hotkey).await.unwrap();
    add_stake(&client, netuid, &miner_alpha_hotkey)
        .await
        .unwrap();

    let signer: PrivateKeySigner = get_signer();
    let signer_public_key = convert_h160_to_public_key(signer.address().as_slice()).unwrap();
    let provider = ProviderBuilder::new()
        .wallet(signer.clone())
        .connect(LOCAL_RPC_URL)
        .await
        .unwrap();

    // deploy contract, get the proxy contract address and contract public key
    let (proxied, contract_public_key) =
        deploy_contract(netuid, &signer, &provider, alpha_hotkey, decision_timeout)
            .await
            .unwrap();
    // force set balance to the contract to avoid insufficient balance error for extrinsic call
    force_set_balance(&client, &AccountId32::from(contract_public_key))
        .await
        .unwrap();
    // burn register neuron to set the contract hotkey and coldkey relations
    burn_register(&client, &proxied).await.unwrap();

    // transfer stake from alith to miner
    transfer_stake(&client, netuid, &miner_alpha_hotkey, &signer_public_key)
        .await
        .unwrap();

    Ok(proxied)
}

/// Convert EVM address to Substrate AccountId32 by hashing "evm:" prefix + address
pub fn convert_h160_to_public_key(eth_address: &[u8]) -> Result<[u8; 32], anyhow::Error> {
    if eth_address.len() != 20 {
        return Err(anyhow::Error::msg(
            "Invalid address length, expected 20 bytes",
        ));
    }

    let mut data = [0u8; 24];
    data[0..4].copy_from_slice(b"evm:");
    data[4..24].copy_from_slice(&eth_address[..]);
    let result = blake2_256(&data);

    Ok(result)
}

pub fn get_signer() -> PrivateKeySigner {
    // get predefined evm account alithe signer, the account is miner's ethereum wallet
    let alithe_private_key = std::env::var("OPEN_EVM_PRIVATE_KEY").unwrap_or_else(|_| {
        "5fb92d6e98884f76de468fa3f6278f8807c48bebc13595d45af5bdc4da702133".to_string()
    });

    let mut signer: PrivateKeySigner = alithe_private_key.parse().unwrap();
    signer.set_chain_id(Some(LOCAL_CHAIN_ID));
    signer
}

#[test]
fn test_convert_h160_to_public_key() {
    let eth_address = H160::from_str("0x0000000000000000000000000000000000000001").unwrap();
    let public_key = convert_h160_to_public_key(eth_address.0.as_slice()).unwrap();
    let hex_public_key = hex::encode(public_key);
    assert_eq!(
        hex_public_key,
        "c16e18ed0b2d27d6fd0dc832a699af7d3adf762cd6d51d780abc460476ad1c58"
    );
}

#[allow(dead_code)]
async fn force_set_balance(
    client: &OnlineClient<PolkadotConfig>,
    account_id: &AccountId32,
) -> Result<(), anyhow::Error> {
    // Connect to local node
    let signer = dev::alice();
    let amount = 1_000_000_000_000u64; // 1000 TAO

    let inner_call =
        bittensorapi::runtime_types::pallet_balances::pallet::Call::force_set_balance {
            who: MultiAddress::Id(account_id.clone()),
            new_free: amount,
        };

    let runtime_call =
        bittensorapi::runtime_types::node_subtensor_runtime::RuntimeCall::Balances(inner_call);

    let call = bittensorapi::tx().sudo().sudo(runtime_call);

    client
        .tx()
        .sign_and_submit_then_watch_default(&call, &signer)
        .await?;

    tokio::time::sleep(Duration::from_secs(3)).await;

    let balance_query = bittensorapi::storage()
        .system()
        .account(AccountId32::from(account_id.clone()));

    let balance = client
        .storage()
        .at_latest()
        .await?
        .fetch(&balance_query)
        .await?
        .unwrap();

    assert_eq!(balance.data.free, amount);

    Ok(())
}

#[allow(dead_code)]
async fn disable_whitelist(client: &OnlineClient<PolkadotConfig>) -> Result<(), anyhow::Error> {
    let storage_query = bittensorapi::storage().evm().disable_whitelist_check();

    let result = client
        .storage()
        .at_latest()
        .await?
        .fetch(&storage_query)
        .await?;

    // already whitelisted
    if let Some(true) = result {
        return Ok(());
    }

    // Create signer from Alice's dev account
    let signer = dev::alice();

    let inner_call =
        bittensorapi::runtime_types::pallet_evm::pallet::Call::disable_whitelist { disabled: true };

    let runtime_call =
        bittensorapi::runtime_types::node_subtensor_runtime::RuntimeCall::EVM(inner_call);

    let call = bittensorapi::tx().sudo().sudo(runtime_call);

    client
        .tx()
        .sign_and_submit_then_watch_default(&call, &signer)
        .await?
        .wait_for_finalized_success()
        .await?;

    let storage_query = bittensorapi::storage().evm().disable_whitelist_check();

    let result = client
        .storage()
        .at_latest()
        .await?
        .fetch(&storage_query)
        .await?;

    assert_eq!(result, Some(true));

    Ok(())
}

// register a new subnet with alice and bob
#[allow(dead_code)]
async fn create_subnet(
    client: &OnlineClient<PolkadotConfig>,
    hotkey: &[u8; 32],
) -> Result<u16, anyhow::Error> {
    // Create signer from Alice's dev account
    let signer = dev::alice();

    let total_networks_query = bittensorapi::storage().subtensor_module().total_networks();
    let total_networks = client
        .storage()
        .at_latest()
        .await?
        .fetch(&total_networks_query)
        .await?
        .unwrap();

    let call = bittensorapi::tx()
        .subtensor_module()
        .register_network(AccountId32::from(hotkey.clone()));
    client
        .tx()
        .sign_and_submit_then_watch_default(&call, &signer)
        .await?
        .wait_for_finalized_success()
        .await?;

    let new_total_networks = client
        .storage()
        .at_latest()
        .await?
        .fetch(&total_networks_query)
        .await?
        .unwrap();

    assert_eq!(new_total_networks, total_networks + 1);

    // wait for 10 blocks for fast blocks
    tokio::time::sleep(Duration::from_secs(6)).await;

    // start the subnet then we can stake to it
    let call = bittensorapi::tx()
        .subtensor_module()
        .start_call(total_networks);

    client
        .tx()
        .sign_and_submit_then_watch_default(&call, &signer)
        .await?
        .wait_for_finalized_success()
        .await?;

    let started_query = bittensorapi::storage()
        .subtensor_module()
        .subtoken_enabled(total_networks);

    let started = client
        .storage()
        .at_latest()
        .await?
        .fetch(&started_query)
        .await?
        .unwrap();
    // confirm the subnet is started
    assert_eq!(started, true);

    Ok(total_networks)
}

// add stake to the subnet with alice
#[allow(dead_code)]
async fn add_stake(
    client: &OnlineClient<PolkadotConfig>,
    netuid: u16,
    hotkey: &[u8; 32],
) -> Result<(), anyhow::Error> {
    // Create signer from Alice's dev account
    let signer = dev::alice();
    let amount = 1_000_000_000_000u64;

    let call = bittensorapi::tx().subtensor_module().add_stake(
        AccountId32::from(hotkey.clone()),
        netuid,
        amount,
    );

    client
        .tx()
        .sign_and_submit_then_watch_default(&call, &signer)
        .await?
        .wait_for_finalized_success()
        .await?;

    let stake = bittensorapi::storage().subtensor_module().alpha(
        AccountId32::from(hotkey.clone()),
        AccountId32::from(signer.public_key()),
        netuid,
    );

    let stake = client
        .storage()
        .at_latest()
        .await?
        .fetch(&stake)
        .await?
        .unwrap();

    assert_eq!(stake.bits > 0, true);

    Ok(())
}

